#include <vector>
#include <cstdint>
uintptr_t FindPattern(const uint8_t* base, size_t size, const char* pat, const char* mask) {
    size_t len = strlen(mask);
    for (size_t i = 0; i + len <= size; ++i) {
        bool found = true;
        for (size_t j = 0; j < len; ++j) {
            if (mask[j] == 'x' && base[i + j] != static_cast<uint8_t>(pat[j])) {
                found = false; break;
            }
        }
        if (found) return reinterpret_cast<uintptr_t>(base + i);
    }
    return 0;
}
